// The types generated by build.rs from
// __synthetic__/generator/proto/generation_set.proto (package generator):
// GenerationSet, FixedPose, JointValue, Range, GenerationJob and
// GenerationDone, each with serde support for protobuf's standard JSON form.
//
// pbjson 0.9's generated serde code writes `&FIELDS` in its error messages,
// which clippy flags (useless_borrows_in_formatting); the code is generated,
// so the lint is allowed here rather than edited away.
#![allow(clippy::useless_borrows_in_formatting)]

include!(concat!(env!("OUT_DIR"), "/generator.rs"));
include!(concat!(env!("OUT_DIR"), "/generator.serde.rs"));
